-- Demo seed (§12.3), anchored to NLQ_TODAY=2026-10-24, on B's real schema.
-- public.users / public.personas are the real tables; recurrent_payments,
-- user_recurrent_payments and payments are unqualified so they land in the dev
-- schema via search_path. The harness sets search_path = "<dev>, public" first.
--
-- amount is stored in MINOR units (BIGINT): major RUB/USD/EUR amounts are *100.
-- Every period (payments row) has a NOT NULL user_id = its assignee. Each
-- recurrent payment has exactly one assignee row in user_recurrent_payments
-- (decision #2). All payments are monthly, interval 1, so run_rate == the sum
-- of active major amounts per currency. The injection title stays as data.

INSERT INTO public.personas (id, name, description) VALUES
